//! The desktop interface's sheet of layout utilities (`NOCTUA.md §4`, "CSS"):
//! Tailwind, run over the classes the interface's markup writes, and kept as
//! the generated file `apps/desktop/src/sheet.rs`, which the document inlines.
//!
//! **Written by `cargo xtask build --sheet`, held by `cargo xtask check`**,
//! which builds it again in memory and refuses a committed sheet that differs
//! — a class written and not built, a sheet edited by hand — as the catalog's
//! generated files are held.
//!
//! **Tailwind is run, never written here**: `xtask/tailwind/package.json`
//! names its command line at an exact version and
//! `xtask/tailwind/pnpm-lock.yaml` every package that brings, each with its
//! integrity hash. Both are copied into `target/tailwind/`, where
//! `pnpm install --frozen-lockfile --ignore-scripts` installs them
//! ([`install_arguments`]) — no package's install script runs, nothing the
//! lockfile does not name is fetched, and `node_modules` never sits in a tree
//! the gates walk.
//!
//! **What it is handed is closed** ([`entry`]): Tailwind's utilities alone —
//! no preflight, none of its theme, so its default palette and spacing emit
//! nothing — **in no cascade layer**, since the design system's sheets are in
//! none either and a utility in a layer could never compose one of its roots:
//! linked after them, a utility weighs as Tailwind's own order weighs its
//! utilities above components, so `shrink` on a design system's line gives it
//! a shrink its own rule withholds — the design system's bridge ([`BRIDGE`], of `noctua-design-dist`
//! at the release the lockfile holds), which maps every `--color-*` utility
//! onto a `--nc-color-*` token and declares no colour (`NOCTUA.md §8.5`), and the classes the markup writes, read here and
//! passed as `@source inline(…)` under `source(none)`: Tailwind never scans
//! the tree, where a Rust keyword such as `static` would become a rule.
//!
//! **Every class is held before Tailwind sees it** ([`judged`]), as lower-case
//! words of letters and digits joined by `-`, with variants before a `:` and,
//! after a utility that takes one ([`FRACTIONAL`]), a fraction of two whole
//! numbers at its end, and nothing else — so an arbitrary value (`w-[13px]`),
//! a colour written out (`bg-[#f00]`), a custom property (`p-(--x)`), an
//! opacity modifier — a colour, a `/` and a share, a palette step's colour
//! whose name ends in a number among them — or an important flag never
//! reaches the sheet; **and the sheet is held
//! after** ([`what_it_lacks`]): every class has a rule — a class Tailwind does
//! not know emits nothing, which would otherwise pass in silence — no rule's
//! selector holds an escaped bracket or parenthesis, and no rule mixes a
//! colour (`color-mix(`), which only a modifier asks of it and the design
//! system's bridge declares none of. **A class is written as a literal right
//! after `class:`** ([`written`]), so a class this reader cannot see is a
//! refusal, never a class the sheet lacks unseen.
//!
//! # What this answers (`NOCTUA.md §2.4`)
//!
//! An arbitrary value — a colour or a size written out — a custom property, a
//! colour mixed by an opacity modifier past the design system's tokens
//! (`§8.8`) and an important flag, each in the markup or in the sheet; and a
//! package's install script running in the gate, or a package the lockfile
//! does not name fetched. **What it does not answer:** what the packages the
//! lockfile names do when they run, which their integrity hashes hold to what
//! was locked and nothing more; and a size a utility takes as a bare value,
//! which Tailwind writes as a length of its own without its spacing scale —
//! `border-8` as eight pixels, `w-px`, `h-screen`, `scale-150` — no token
//! being asked for it.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

use crate::ui;

/// The generated file, relative to the repository.
pub(crate) const SHEET: &str = "apps/desktop/src/sheet.rs";

/// The markup's sources, relative to the repository: every Rust file under
/// it but [`SHEET`].
pub(crate) const MARKUP: &str = "apps/desktop/src";

/// Tailwind's package and its lockfile, relative to the repository.
pub(crate) const PACKAGE: [&str; 2] = [
    "xtask/tailwind/package.json",
    "xtask/tailwind/pnpm-lock.yaml",
];

/// Where Tailwind is installed and run, relative to the repository.
const OUT: &str = "target/tailwind";

/// The design system's bridge, by the name `noctua-design-dist` ships it
/// under.
const BRIDGE: &str = "tailwind/bridge.css";

/// What the generated file says above the sheet.
const HEADER: &str = "//! Generated by `cargo xtask build --sheet` from the classes `apps/desktop/src` writes — do not edit.\n//!\n//! Tailwind's utilities over the design system's Tailwind bridge, from\n//! `noctua-design-dist`, built by `xtask/src/tailwind.rs`, which says how.\n\n/// The interface's layout utilities, one minified sheet.\npub const SHEET: &str = ";

/// Every class `text` writes as `class: "…"`, with its line, or the line of
/// a `class:` that is not followed by a string literal.
pub(crate) fn written(text: &str) -> Result<Vec<(usize, String)>, usize> {
    let mut found = Vec::new();
    for (at, _) in text.match_indices("class:") {
        let before = text[..at].chars().next_back();
        if before.is_some_and(|character| character.is_alphanumeric() || character == '_') {
            continue;
        }
        let line = text[..at].matches('\n').count() + 1;
        let after = text[at + "class:".len()..].trim_start();
        let Some(literal) = after.strip_prefix('"') else {
            return Err(line);
        };
        let Some(end) = literal.find('"') else {
            return Err(line);
        };
        found.extend(
            literal[..end]
                .split_whitespace()
                .map(|class| (line, class.to_owned())),
        );
    }
    Ok(found)
}

/// The utilities a fraction may follow: each a size or a place Tailwind
/// writes as that share of its box — a width of one half as half the width of
/// the box around it — and none a colour, whose `/` is an opacity modifier.
pub(crate) const FRACTIONAL: [&str; 20] = [
    "w",
    "h",
    "size",
    "min-w",
    "max-w",
    "min-h",
    "max-h",
    "basis",
    "inset",
    "inset-x",
    "inset-y",
    "top",
    "right",
    "bottom",
    "left",
    "start",
    "end",
    "translate-x",
    "translate-y",
    "aspect",
];

/// Whether `class` is a class the sheet may hold: lower-case words of letters
/// and digits joined by `-`, variants before a `:`, and a fraction of two
/// whole numbers at its end after a utility of [`FRACTIONAL`]; the sentence
/// saying what it is not, otherwise.
pub(crate) fn judged(class: &str) -> Result<(), String> {
    let refused = |why: &str| Err(format!("`{class}` {why}"));
    let utility = class.rsplit(':').next().unwrap_or(class);
    let variants = &class[..class.len() - utility.len()];
    for variant in variants.split(':').filter(|variant| !variant.is_empty()) {
        if !is_words(variant) {
            return refused("has a variant that is not lower-case words joined by `-`");
        }
    }
    if variants.contains("::") || class.starts_with(':') {
        return refused("has an empty variant");
    }
    let (whole, fraction) = match utility.split_once('/') {
        Some((whole, fraction)) => (whole, Some(fraction)),
        None => (utility, None),
    };
    if !is_words(whole) {
        return refused(
            "is not lower-case words of letters and digits joined by `-`: an arbitrary value, \
             a colour written out, a custom property and an important flag are refused",
        );
    }
    if let Some(fraction) = fraction {
        let (root, numerator) = whole.rsplit_once('-').unwrap_or(("", whole));
        if !is_number(numerator) || !is_number(fraction) || !FRACTIONAL.contains(&root) {
            return refused(
                "has a `/` that is not a fraction of two whole numbers after a size or a place: \
                 an opacity modifier mixes a colour the design system did not",
            );
        }
    }
    Ok(())
}

/// Whether `text` is lower-case words of ASCII letters and digits joined by
/// one `-` each.
fn is_words(text: &str) -> bool {
    !text.is_empty()
        && text.split('-').all(|word| {
            !word.is_empty()
                && word
                    .chars()
                    .all(|character| character.is_ascii_lowercase() || character.is_ascii_digit())
        })
}

/// Whether `text` is a whole number written in ASCII digits.
fn is_number(text: &str) -> bool {
    !text.is_empty() && text.chars().all(|character| character.is_ascii_digit())
}

/// Every class the markup under `root` writes, each once, in order; or every
/// refusal, naming its file and line.
pub(crate) fn classes(root: &Path) -> Result<BTreeSet<String>, Vec<String>> {
    let mut sources: Vec<PathBuf> = Vec::new();
    crate::gates::walk(&root.join(MARKUP), &mut |path| {
        if path.extension().is_some_and(|extension| extension == "rs") {
            sources.push(path.to_path_buf());
        }
    })
    .map_err(|problem| vec![problem])?;
    let mut classes = BTreeSet::new();
    let mut refused = Vec::new();
    for path in sources {
        let relative = crate::relative_to(root, &path);
        if relative == SHEET {
            continue;
        }
        let text = std::fs::read_to_string(&path)
            .map_err(|error| vec![format!("{relative} could not be read: {error}")])?;
        match written(&text) {
            Err(line) => refused.push(format!(
                "{relative}:{line} — a `class:` that is not a string literal, whose classes \
                 the sheet cannot be built for: write each class out, as `class: \"flex\"`"
            )),
            Ok(found) => {
                for (line, class) in found {
                    match judged(&class) {
                        Ok(()) => {
                            classes.insert(class);
                        }
                        Err(why) => refused.push(format!("{relative}:{line} — {why}")),
                    }
                }
            }
        }
    }
    if refused.is_empty() {
        Ok(classes)
    } else {
        Err(refused)
    }
}

/// The entry Tailwind reads, for `classes`: its utilities alone, in no
/// cascade layer, the bridge beside it, and the classes, inline.
pub(crate) fn entry(classes: &BTreeSet<String>) -> String {
    let inline = classes.iter().cloned().collect::<Vec<_>>().join(" ");
    format!(
        "@import \"tailwindcss/utilities.css\" source(none);\n\
         @import \"./bridge.css\";\n\
         @source inline(\"{inline}\");\n"
    )
}

/// What `css` lacks for `classes`: each class with no rule, each rule whose
/// selector holds an escaped bracket or parenthesis, and a colour mixed.
pub(crate) fn what_it_lacks(css: &str, classes: &BTreeSet<String>) -> Vec<String> {
    let mut lacks = Vec::new();
    for class in classes {
        let selector = format!(".{}", class.replace(':', "\\:").replace('/', "\\/"));
        let has_a_rule = css.match_indices(&selector).any(|(at, _)| {
            css[at + selector.len()..]
                .chars()
                .next()
                .is_some_and(|next| {
                    !(next.is_ascii_alphanumeric() || matches!(next, '-' | '_' | '\\'))
                })
        });
        if !has_a_rule {
            lacks.push(format!(
                "`{class}` has no rule in the sheet: a class Tailwind does not know — its \
                 default palette and spacing are not imported — emits nothing"
            ));
        }
    }
    for escaped in ["\\[", "\\("] {
        if css.contains(escaped) {
            lacks.push(format!(
                "the sheet holds a selector with `{escaped}`, which is an arbitrary value's"
            ));
        }
    }
    if css.contains("color-mix(") {
        lacks.push(
            "the sheet mixes a colour (`color-mix(`), which only an opacity modifier asks of it: \
             a colour the design system did not define"
                .to_owned(),
        );
    }
    lacks
}

/// The generated file holding `css`.
pub(crate) fn as_rust(css: &str) -> String {
    format!("{HEADER}{css:?};\n")
}

/// The program `name` as this system finds it on `PATH`: by each extension
/// `PATHEXT` lists, where it lists any — Windows' `pnpm.cmd` — and as
/// written otherwise.
fn on_path(name: &str) -> Option<PathBuf> {
    let extensions: Vec<String> = std::env::var("PATHEXT")
        .map(|listed| {
            listed
                .split(';')
                .filter(|extension| !extension.is_empty())
                .map(str::to_ascii_lowercase)
                .collect()
        })
        .unwrap_or_default();
    let names: Vec<String> = if extensions.is_empty() {
        vec![name.to_owned()]
    } else {
        extensions
            .iter()
            .map(|extension| format!("{name}{extension}"))
            .collect()
    };
    std::env::split_paths(&std::env::var_os("PATH")?)
        .flat_map(|directory| names.iter().map(move |name| directory.join(name)))
        .find(|candidate| candidate.is_file())
}

/// Runs pnpm in `directory` with `args`, and answers what it printed, or
/// why it failed.
fn pnpm(directory: &Path, args: &[&str]) -> Result<String, String> {
    let program = on_path("pnpm").ok_or_else(|| {
        "pnpm is not on `PATH`, and the desktop's sheet is built by Tailwind through it: \
         install the version `xtask/tailwind/package.json` was locked with (`npm install -g \
         pnpm@11.9.0`), or run under the nix shell `AGENTS.md` names"
            .to_owned()
    })?;
    #[expect(
        clippy::disallowed_methods,
        reason = "pnpm, which installs and runs Tailwind; what it prints is read, not printed"
    )]
    let output = std::process::Command::new(program)
        .args(args)
        .current_dir(directory)
        .stdin(std::process::Stdio::null())
        .output()
        .map_err(|error| format!("pnpm could not be run: {error}"))?;
    let mut said = String::from_utf8_lossy(&output.stdout).into_owned();
    said.push_str(&String::from_utf8_lossy(&output.stderr));
    if output.status.success() {
        Ok(said)
    } else {
        Err(format!("pnpm {} failed: {}", args.join(" "), said.trim()))
    }
}

/// Writes `bytes` at `path` where it holds anything else.
fn written_if_changed(path: &Path, bytes: &[u8]) -> Result<(), String> {
    if std::fs::read(path).is_ok_and(|held| held == bytes) {
        return Ok(());
    }
    std::fs::write(path, bytes)
        .map_err(|error| format!("{} could not be written: {error}", path.display()))
}

/// What pnpm installs Tailwind with: the lockfile, frozen — a package it does
/// not name is refused, never resolved — no package's install script run,
/// and nothing fetched where `offline`.
// allow-logging: `install_arguments` hands back pnpm's flags, each a literal written here, never text a caller gave
pub(crate) fn install_arguments(offline: bool) -> Vec<&'static str> {
    let frozen = ["install", "--frozen-lockfile", "--ignore-scripts"];
    frozen
        .into_iter()
        .chain(offline.then_some("--offline"))
        .collect()
}

/// The generated file for the markup under `root`, built in memory: Tailwind
/// installed under `target/` and run there, `offline` asking pnpm to fetch
/// nothing.
///
/// # Errors
///
/// Every class refused, naming its file and line; and the install, the bridge
/// or Tailwind failing, or a sheet that lacks what [`what_it_lacks`] reads.
pub(crate) fn built(root: &Path, offline: bool) -> Result<(String, usize), String> {
    let classes = classes(root).map_err(|refused| refused.join("\n"))?;
    let out = root.join(OUT);
    std::fs::create_dir_all(&out)
        .map_err(|error| format!("{} could not be made: {error}", out.display()))?;
    for package in PACKAGE {
        let bytes = std::fs::read(root.join(package))
            .map_err(|error| format!("{package} could not be read: {error}"))?;
        let name = Path::new(package).file_name().unwrap_or_default();
        written_if_changed(&out.join(name), &bytes)?;
    }
    let bridge = noctua_design_dist::FILES
        .iter()
        .find(|(name, _)| *name == BRIDGE)
        .map(|(_, text)| *text)
        .ok_or_else(|| {
            format!(
                "noctua-design-dist ships no `{BRIDGE}`, which the sheet maps the colour \
                 utilities through: take a release of the design system that ships it"
            )
        })?;
    written_if_changed(&out.join("bridge.css"), bridge.as_bytes())?;
    written_if_changed(&out.join("entry.css"), entry(&classes).as_bytes())?;
    pnpm(&out, &install_arguments(offline))?;
    let _ = std::fs::remove_file(out.join("sheet.css"));
    pnpm(
        &out,
        &[
            "exec",
            "tailwindcss",
            "--input",
            "entry.css",
            "--output",
            "sheet.css",
            "--minify",
        ],
    )?;
    let css = std::fs::read_to_string(out.join("sheet.css"))
        .map_err(|error| format!("Tailwind wrote no sheet: {error}"))?;
    let lacks = what_it_lacks(&css, &classes);
    if !lacks.is_empty() {
        return Err(lacks.join("\n"));
    }
    Ok((as_rust(css.trim_end()), classes.len()))
}

/// What `cargo xtask build --sheet` runs: the sheet built, and written where
/// it changed.
///
/// # Errors
///
/// What [`built`] refuses, and a sheet that could not be written.
pub(crate) fn run(root: &Path) -> Result<(), String> {
    ui::heading("the desktop's sheet");
    let (file, classes) = built(root, false)?;
    let path = root.join(SHEET);
    let held = std::fs::read_to_string(&path).unwrap_or_default();
    if held == file {
        ui::ok(&format!(
            "{SHEET} holds the rules of {classes} class(es), unchanged"
        ));
    } else {
        std::fs::write(&path, &file)
            .map_err(|error| format!("{SHEET} could not be written: {error}"))?;
        ui::ok(&format!(
            "{SHEET} rewritten, with the rules of {classes} class(es)"
        ));
    }
    Ok(())
}

/// The sheet's step of `check`: built again in memory, and held to the one
/// committed.
pub(crate) fn check(root: &Path, offline: bool, failures: &mut Vec<String>) {
    match built(root, offline) {
        Err(problem) => {
            for line in problem.lines() {
                ui::failure(line);
            }
            failures.push("the desktop's sheet could not be built".to_owned());
        }
        Ok((file, classes)) => {
            if std::fs::read_to_string(root.join(SHEET)).is_ok_and(|held| held == file) {
                ui::ok(&format!(
                    "{SHEET} is what Tailwind builds for the {classes} class(es) the markup writes"
                ));
            } else {
                ui::failure(&format!(
                    "{SHEET} is not what Tailwind builds for the classes the markup writes: run \
                     `cargo xtask build --sheet`, and commit what it writes"
                ));
                failures.push("the desktop's sheet is out of sync".to_owned());
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    use super::{as_rust, entry, install_arguments, judged, what_it_lacks, written};

    /// A class written as a literal after `class:` is read, each word one
    /// class, with its line; one written any other way is refused at its
    /// line; and a word that only ends in `class` is no attribute.
    #[test]
    fn a_class_is_read_only_as_a_literal_after_class() {
        let text = "rsx! {\n    main { class: \"flex  h-full\",\n        div { class:\"w-full\" }\n    }\n}\nlet subclass: \"x\";\n";
        assert_eq!(
            written(text),
            Ok(vec![
                (2, "flex".to_owned()),
                (2, "h-full".to_owned()),
                (3, "w-full".to_owned()),
            ])
        );
        assert_eq!(
            written("a\nb { class: if on { \"flex\" } else { \"\" } }"),
            Err(2)
        );
        assert_eq!(written("c { class: classes }"), Err(1));
        assert_eq!(written("c { class: \"unclosed }"), Err(1));
        assert_eq!(written("nothing here"), Ok(Vec::new()));
    }

    /// Lower-case words joined by `-`, with variants and a fraction, are
    /// admitted; an arbitrary value, a colour written out, a custom property,
    /// an opacity modifier, an important flag and anything outside the
    /// closed set of characters are refused.
    #[test]
    fn only_the_closed_set_of_classes_is_admitted() {
        for admitted in [
            "flex",
            "flex-col",
            "h-full",
            "grid-cols-12",
            "md:flex",
            "dark:md:hidden",
            "w-1/2",
            "basis-11/12",
            "max-h-1/3",
            "translate-x-1/2",
            "aspect-16/9",
            "bg-surface",
        ] {
            assert_eq!(judged(admitted), Ok(()), "{admitted}");
        }
        for refused in [
            "w-[13px]",
            "bg-[#ff0000]",
            "[mask-type:luminance]",
            "p-(--gap)",
            "bg-accent/50",
            "bg-chart-1/50",
            "text-chart-wide-3/25",
            "border-gray-18/5",
            "1/2",
            "w-1/x",
            "w-/2",
            "!flex",
            "Flex",
            "flex_col",
            "flex--col",
            "-mt-4",
            "flex-",
            "md::flex",
            ":flex",
            "hover:",
            "[&>*]:flex",
            "h-1.5",
            "bg-surface!",
        ] {
            assert!(judged(refused).is_err(), "{refused} was admitted");
        }
    }

    /// The entry imports Tailwind's utilities alone, with no source scanned,
    /// the bridge beside it, and the classes inline.
    #[test]
    fn the_entry_imports_the_utilities_alone_and_names_every_class() {
        let classes: BTreeSet<String> =
            ["h-full", "flex"].iter().map(|c| (*c).to_owned()).collect();
        let written = entry(&classes);
        assert!(written.contains("@import \"tailwindcss/utilities.css\" source(none);"));
        assert!(written.contains("@import \"./bridge.css\";"));
        assert!(
            !written.contains("layer"),
            "the utilities are in no cascade layer, as the design system's sheets are not: \
             {written}"
        );
        assert!(written.contains("@source inline(\"flex h-full\");"));
        assert!(!written.contains("preflight") && !written.contains("theme.css"));
        assert!(
            !written.contains("@source \""),
            "no path is scanned: {written}"
        );
    }

    /// A class with no rule, and a selector with an arbitrary value's escape,
    /// are each named; a class whose selector only begins another's has no
    /// rule.
    #[test]
    fn a_class_with_no_rule_and_an_escaped_bracket_are_named() {
        let classes: BTreeSet<String> = ["flex", "flex-col", "md:flex", "w-1/2", "p-5"]
            .iter()
            .map(|c| (*c).to_owned())
            .collect();
        let css = ".flex{display:flex}.flex-col{flex-direction:column}@media (width>=48rem){.md\\:flex{display:flex}}.w-1\\/2{width:50%}";
        assert_eq!(
            what_it_lacks(css, &classes),
            [
                "`p-5` has no rule in the sheet: a class Tailwind does not know — its default \
              palette and spacing are not imported — emits nothing"
            ]
        );
        let only_a_longer = ".flex-col{flex-direction:column}";
        let flex: BTreeSet<String> = std::iter::once("flex".to_owned()).collect();
        assert_eq!(what_it_lacks(only_a_longer, &flex).len(), 1);
        let arbitrary =
            ".flex{display:flex}.w-\\[13px\\]{width:13px}.p-\\(--x\\){padding:var(--x)}";
        assert_eq!(what_it_lacks(arbitrary, &flex).len(), 2);
        let mixed = ".flex{display:flex}@supports (color:color-mix(in lab, red, red)){.flex{color:\
                     color-mix(in oklab, var(--nc-chart-1) 50%, transparent)}}";
        assert_eq!(
            what_it_lacks(mixed, &flex),
            [
                "the sheet mixes a colour (`color-mix(`), which only an opacity modifier asks of \
                 it: a colour the design system did not define"
            ]
        );
    }

    /// Tailwind is installed from the lockfile alone, frozen, and runs no
    /// package's install script, online or not; and fetches nothing offline.
    #[test]
    fn tailwind_is_installed_frozen_with_no_install_script() {
        assert_eq!(
            install_arguments(false),
            ["install", "--frozen-lockfile", "--ignore-scripts"]
        );
        assert_eq!(
            install_arguments(true),
            [
                "install",
                "--frozen-lockfile",
                "--ignore-scripts",
                "--offline"
            ]
        );
    }

    /// The generated file is the sheet as one string literal under its
    /// header, which says it is generated and how to build it.
    #[test]
    fn the_generated_file_holds_the_sheet_as_one_literal() {
        let file = as_rust(".a{b:\"c\"}\n.d{}");
        assert!(file.starts_with("//! Generated by `cargo xtask build --sheet`"));
        assert!(
            file.ends_with("pub const SHEET: &str = \".a{b:\\\"c\\\"}\\n.d{}\";\n"),
            "{file}"
        );
    }
}
